# Cross-language concept search: map query terms to language-neutral concept ids,
# then retrieve documents tagged with those concepts in any language.
concepts = {'C1': {'en': ['dog'], 'es': ['perro'], 'fr': ['chien']}}
docs = {'d1': ('en', ['C1']), 'd2': ('fr', ['C1']), 'd3': ('es', ['C2'])}
def concept_of(term, lang):
    term = term.lower()
    for cid, names in concepts.items():
        if term in [t.lower() for t in names.get(lang, [])]:
            return cid
    return None
query = "perro"
lang = "es"
cids = {c for t in query.split() if (c := concept_of(t, lang))}
print("Query:", query, f"({lang}) -> concepts:", sorted(cids) or "none")
for doc_id, (dlang, dcids) in docs.items():
    if cids & set(dcids):
        print(f"MATCH {doc_id} [{dlang}]: concepts {sorted(set(dcids) & cids)}")

